import React, { useState } from 'react';

const Contact = ({ data, socialLinks }) => {
  const [form, setForm]   = useState({ name:'', email:'', subject:'', message:'' });
  const [status, setStatus] = useState('idle');

  const handleChange = e => setForm(f => ({ ...f, [e.target.name]: e.target.value }));
  const handleSubmit = e => {
    e.preventDefault(); setStatus('sending');
    setTimeout(() => setStatus('sent'), 1500);
  };

  const contactItems = [
    { icon:'✉', label:'Email',    value:data?.email,    href:`mailto:${data?.email}` },
    { icon:'📞', label:'Phone',    value:data?.phone,    href:`tel:${data?.phone}` },
    { icon:'📍', label:'Location', value:data?.location, href:null },
  ];

  const inputStyle = {
    width:'100%', padding:'0.85rem 1.2rem',
    background:'rgba(34,18,40,0.6)',
    border:'1px solid rgba(232,121,154,0.2)',
    borderRadius:12, color:'#fdf0f4',
    fontFamily:"'Nunito', sans-serif", fontSize:'0.9rem',
    outline:'none', transition:'border-color 0.25s ease',
  };

  return (
    <section style={{ padding:'100px 0' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        <div style={{ textAlign:'center', marginBottom:60 }}>
          <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 06. contact
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            Let's <span style={{ color:'#e8799a', fontStyle:'italic' }}>Connect</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
          <p style={{ fontFamily:"'Nunito'", fontSize:'1rem', color:'rgba(253,240,244,0.5)', marginTop:'1.5rem', maxWidth:500, margin:'1.5rem auto 0' }}>
            Have a project in mind or want to collaborate? Feel free to reach out! 🌸
          </p>
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'1fr 1.5fr', gap:'2rem', alignItems:'start' }} className="contact-grid">

          {/* Left info */}
          <div style={{ display:'flex', flexDirection:'column', gap:'1rem' }}>
            {contactItems.map((item,i) => (
              <div key={i} style={{
                background:'rgba(34,18,40,0.72)',
                border:'1px solid rgba(232,121,154,0.14)',
                borderRadius:16, backdropFilter:'blur(14px)',
                padding:'1.25rem 1.5rem',
                display:'flex', alignItems:'center', gap:'1rem',
                transition:'all 0.3s ease',
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.4)'; e.currentTarget.style.transform='translateX(5px)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.14)'; e.currentTarget.style.transform='translateX(0)'; }}
              >
                <div style={{ width:44, height:44, borderRadius:'50%', background:'rgba(232,121,154,0.12)', border:'1px solid rgba(232,121,154,0.25)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.1rem', flexShrink:0 }}>{item.icon}</div>
                <div>
                  <div style={{ fontFamily:"'DM Mono'", fontSize:'0.7rem', color:'#e8799a', letterSpacing:'0.1em', textTransform:'uppercase', marginBottom:'0.2rem' }}>{item.label}</div>
                  {item.href ? (
                    <a href={item.href} style={{ fontFamily:"'Nunito'", fontSize:'0.88rem', color:'#fdf0f4', textDecoration:'none' }}>{item.value}</a>
                  ) : (
                    <span style={{ fontFamily:"'Nunito'", fontSize:'0.88rem', color:'#fdf0f4' }}>{item.value}</span>
                  )}
                </div>
              </div>
            ))}

            {/* Social */}
            <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:16, padding:'1.25rem 1.5rem' }}>
              <div style={{ fontFamily:"'DM Mono'", fontSize:'0.7rem', color:'#e8799a', letterSpacing:'0.1em', marginBottom:'0.75rem', textTransform:'uppercase' }}>Follow Me</div>
              <div style={{ display:'flex', gap:'0.75rem' }}>
                {[
                  { href:socialLinks?.github, label:'GitHub', icon:(
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0 0 24 12c0-6.63-5.37-12-12-12z"/>
                    </svg>
                  )},
                  { href:socialLinks?.linkedin, label:'LinkedIn', icon:(
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 0 1-2.063-2.065 2.064 2.064 0 1 1 2.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/>
                    </svg>
                  )},
                ].map(link => (
                  <a key={link.label} href={link.href} target="_blank" rel="noopener noreferrer"
                    style={{ width:44, height:44, borderRadius:'50%', display:'flex', alignItems:'center', justifyContent:'center', background:'rgba(232,121,154,0.1)', border:'1px solid rgba(232,121,154,0.2)', color:'rgba(253,240,244,0.65)', transition:'all 0.3s ease' }}
                    onMouseEnter={e => { e.currentTarget.style.background='rgba(232,121,154,0.2)'; e.currentTarget.style.color='#e8799a'; e.currentTarget.style.transform='translateY(-3px)'; }}
                    onMouseLeave={e => { e.currentTarget.style.background='rgba(232,121,154,0.1)'; e.currentTarget.style.color='rgba(253,240,244,0.65)'; e.currentTarget.style.transform='translateY(0)'; }}
                  >{link.icon}</a>
                ))}
              </div>
            </div>
          </div>

          {/* Right: form */}
          <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:22, backdropFilter:'blur(14px)', padding:'2rem' }}>
            {status === 'sent' ? (
              <div style={{ textAlign:'center', padding:'3rem 0' }}>
                <div style={{ fontSize:'3.5rem', marginBottom:'1rem' }}>🌸</div>
                <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.5rem', fontWeight:700, color:'#e8799a', marginBottom:'0.5rem' }}>Message Sent!</h3>
                <p style={{ fontFamily:"'Nunito'", color:'rgba(253,240,244,0.6)' }}>Thank you for reaching out. I'll get back to you soon!</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} style={{ display:'flex', flexDirection:'column', gap:'1.25rem' }}>
                <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'1rem' }}>
                  {['name','email'].map(field => (
                    <div key={field}>
                      <label style={{ fontFamily:"'DM Mono'", fontSize:'0.72rem', color:'#e8799a', letterSpacing:'0.08em', textTransform:'uppercase', marginBottom:'0.4rem', display:'block' }}>{field}</label>
                      <input name={field} value={form[field]} onChange={handleChange}
                        type={field === 'email' ? 'email' : 'text'} required
                        style={inputStyle}
                        onFocus={e => e.target.style.borderColor='rgba(232,121,154,0.55)'}
                        onBlur={e => e.target.style.borderColor='rgba(232,121,154,0.2)'}
                        placeholder={field === 'name' ? 'Your Name' : 'your@email.com'}
                      />
                    </div>
                  ))}
                </div>
                <div>
                  <label style={{ fontFamily:"'DM Mono'", fontSize:'0.72rem', color:'#e8799a', letterSpacing:'0.08em', textTransform:'uppercase', marginBottom:'0.4rem', display:'block' }}>Subject</label>
                  <input name="subject" value={form.subject} onChange={handleChange} required
                    style={inputStyle}
                    onFocus={e => e.target.style.borderColor='rgba(232,121,154,0.55)'}
                    onBlur={e => e.target.style.borderColor='rgba(232,121,154,0.2)'}
                    placeholder="Project Collaboration"
                  />
                </div>
                <div>
                  <label style={{ fontFamily:"'DM Mono'", fontSize:'0.72rem', color:'#e8799a', letterSpacing:'0.08em', textTransform:'uppercase', marginBottom:'0.4rem', display:'block' }}>Message</label>
                  <textarea name="message" value={form.message} onChange={handleChange} required rows={5}
                    style={{ ...inputStyle, resize:'vertical', minHeight:130 }}
                    onFocus={e => e.target.style.borderColor='rgba(232,121,154,0.55)'}
                    onBlur={e => e.target.style.borderColor='rgba(232,121,154,0.2)'}
                    placeholder="Tell me about your project..."
                  />
                </div>
                <button type="submit"
                  style={{
                    padding:'0.95rem', borderRadius:'50px',
                    background: status === 'sending' ? 'rgba(232,121,154,0.4)' : 'linear-gradient(135deg,#e8799a,#b882d4)',
                    color:'#fff', fontFamily:"'Nunito'", fontSize:'1rem', fontWeight:700,
                    border:'none', cursor: status === 'sending' ? 'not-allowed' : 'pointer',
                    transition:'all 0.3s ease',
                    boxShadow:'0 4px 22px rgba(232,121,154,0.35)',
                  }}
                  disabled={status === 'sending'}
                  onMouseEnter={e => { if (status !== 'sending') e.currentTarget.style.boxShadow='0 8px 32px rgba(232,121,154,0.5)'; }}
                  onMouseLeave={e => { e.currentTarget.style.boxShadow='0 4px 22px rgba(232,121,154,0.35)'; }}
                >
                  {status === 'sending' ? '🌸 Sending…' : '✉ Send Message'}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width:768px) { .contact-grid { grid-template-columns:1fr !important; } }
      `}</style>
    </section>
  );
};

export default Contact;
